      <div class="cart-total-row"><span><?php echo $t['cart_total']; ?></span><span id="cartTotal"><?php echo $t['currency']; ?> 0</span></div>
      <input type="text" id="custName" placeholder="<?php echo $t['cart_name']; ?>">
      <input type="tel" id="custPhone" placeholder="<?php echo $t['cart_phone']; ?>">
      <button class="btn cart-checkout" id="cartCheckout"><?php echo $t['cart_checkout']; ?></button>
      <p id="cartMsg" class="form-msg"></p>
    </div>
  </aside>

  <script>
    var API_BASE="http://localhost:5000",LOCALE="<?php echo ($lang==='ar')?'ar-EG':'en-US';?>",CURRENCY="<?php echo $t['currency'];?>",MSG_SENDING="<?php echo $t['form_sending'];?>",MSG_SUCCESS="<?php echo $t['form_success'];?>",MSG_ERROR="<?php echo $t['form_error'];?>",CART_EMPTY="<?php echo $t['cart_empty'];?>",CART_OK="<?php echo $t['cart_success'];?>",CART_ERR="<?php echo $t['cart_error'];?>";
    function money(n){return CURRENCY+" "+Number(n).toLocaleString(LOCALE);}

    /* Mobile menu */
    var mt=document.querySelector('.menu-toggle');
    if(mt)mt.addEventListener('click',function(){document.querySelector('.nav-links').classList.toggle('open');});

    /* Animated counters */
    var counters=document.querySelectorAll('.counter .val');
    if(counters.length){
      var obs=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(!entry.isIntersecting)return;var el=entry.target,target=+el.dataset.target,step=Math.max(1,Math.floor(target/60)),cur=0;var tick=setInterval(function(){cur+=step;if(cur>=target){cur=target;clearInterval(tick);}el.textContent=cur.toLocaleString(LOCALE);},25);obs.unobserve(el);});},{threshold:0.4});
      counters.forEach(function(c){obs.observe(c);});
    }

    /* Contact form */
    var form=document.getElementById('contactForm');
    if(form){var fmsg=document.getElementById('formMsg');form.addEventListener('submit',function(e){e.preventDefault();fmsg.textContent=MSG_SENDING;fmsg.className='form-msg';var payload={name:form.elements['name'].value,phone:form.elements['phone'].value,email:form.elements['email'].value,business_type:form.elements['business_type'].value,message:form.elements['message'].value};fetch(API_BASE+'/api/contact',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}).then(function(r){return r.json();}).then(function(d){if(d.ok){fmsg.textContent=MSG_SUCCESS;fmsg.className='form-msg success';form.reset();}else{fmsg.textContent=MSG_ERROR;fmsg.className='form-msg error';}}).catch(function(){fmsg.textContent=MSG_ERROR;fmsg.className='form-msg error';});});}

    /* Cart */
    var CART_KEY='omenu_cart',cart=JSON.parse(localStorage.getItem(CART_KEY)||'[]');
    var cartDrawer=document.getElementById('cartDrawer'),cartOverlay=document.getElementById('cartOverlay'),cartItemsEl=document.getElementById('cartItems'),cartTotalEl=document.getElementById('cartTotal'),cartCountEl=document.getElementById('cartCount'),cartMsg=document.getElementById('cartMsg');
    function saveCart(){localStorage.setItem(CART_KEY,JSON.stringify(cart));}
    function addToCart(name,price){var found=cart.find(function(i){return i.name===name;});if(found){found.qty+=1;}else{cart.push({name:name,price:price,qty:1});}saveCart();renderCart();openCart();}
    function changeQty(index,delta){cart[index].qty+=delta;if(cart[index].qty<=0)cart.splice(index,1);saveCart();renderCart();}
    function renderCart(){var count=cart.reduce(function(s,i){return s+i.qty;},0);cartCountEl.textContent=count;cartCountEl.style.display=count>0?'flex':'none';if(cart.length===0){cartItemsEl.innerHTML='<p class="cart-empty">'+CART_EMPTY+'</p>';}else{cartItemsEl.innerHTML=cart.map(function(i,idx){return'<div class="cart-item"><div class="ci-info"><b>'+i.name+'</b><span>'+money(i.price)+'</span></div><div class="ci-qty"><button data-act="dec" data-i="'+idx+'">-</button><span>'+i.qty+'</span><button data-act="inc" data-i="'+idx+'">+</button></div></div>';}).join('');}var total=cart.reduce(function(s,i){return s+i.price*i.qty;},0);cartTotalEl.textContent=money(total);}
    document.querySelectorAll('.add-to-cart').forEach(function(b){b.addEventListener('click',function(){addToCart(b.dataset.name,parseFloat(b.dataset.price));});});
    cartItemsEl.addEventListener('click',function(e){var btn=e.target.closest('button');if(!btn)return;var i=+btn.dataset.i;if(btn.dataset.act==='inc')changeQty(i,+1);if(btn.dataset.act==='dec')changeQty(i,-1);});
    function openCart(){cartDrawer.classList.add('open');cartOverlay.classList.add('show');cartMsg.textContent='';}
    function closeCart(){cartDrawer.classList.remove('open');cartOverlay.classList.remove('show');}
    document.getElementById('cartBtn').addEventListener('click',openCart);
    cartOverlay.addEventListener('click',closeCart);
    document.getElementById('cartClose').addEventListener('click',closeCart);
    document.getElementById('cartCheckout').addEventListener('click',function(){if(cart.length===0){cartMsg.textContent=CART_EMPTY;cartMsg.className='form-msg error';return;}cartMsg.textContent=MSG_SENDING;cartMsg.className='form-msg';fetch(API_BASE+'/api/order',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({items:cart,customer_name:document.getElementById('custName').value,customer_phone:document.getElementById('custPhone').value})}).then(function(r){return r.json();}).then(function(d){if(d.ok){cartMsg.textContent=CART_OK;cartMsg.className='form-msg success';cart=[];saveCart();renderCart();}else{cartMsg.textContent=CART_ERR;cartMsg.className='form-msg error';}}).catch(function(){cartMsg.textContent=CART_ERR;cartMsg.className='form-msg error';});});

    /* Scroll reveal */
    (function(){
      var els=document.querySelectorAll('.reveal');
      if(!els.length)return;
      if(!('IntersectionObserver' in window)){els.forEach(function(el){el.classList.add('visible');});return;}
      var ro=new IntersectionObserver(function(entries){entries.forEach(function(en){if(en.isIntersecting){en.target.classList.add('visible');ro.unobserve(en.target);}});},{threshold:0.1});
      els.forEach(function(el){ro.observe(el);});
    })();

    renderCart();
  </script>
</body>
</html>
